import csv
from io import StringIO

def minutes_from_csv(text):
    reader = csv.DictReader(StringIO(text))
    if reader.fieldnames is None or 'minutes' not in reader.fieldnames:
        raise ValueError('CSV needs a minutes column')
    result = []
    for row_number, row in enumerate(reader, start=2):
        try:
            value = int(row['minutes'])
        except (TypeError, ValueError) as error:
            raise ValueError(f'Row {row_number}: invalid minutes') from error
        if value < 0:
            raise ValueError(f'Row {row_number}: negative minutes')
        result.append(value)
    return result

assert minutes_from_csv('lesson,minutes\nloops,20\nfiles,35\n') == [20, 35]
